  // ---------- Задания 1–3. Работа с небольшим текстом ----------
  add("r0-1", [
    { t: "input", q: "Подбери противительный союз или вводное слово на место пропуска и запиши его.\n«(1) Утром шёл сильный дождь. (2) <…> к обеду небо прояснилось и выглянуло солнце.»", a: ["однако", "но"], e: "Предложение 2 противопоставлено первому: «Однако к обеду небо прояснилось…»." },
    { t: "input", q: "Подбери слово со значением следствия на место пропуска и запиши его.\n«(1) Лёд на реке ещё тонкий. (2) <…> выходить на него опасно.»", a: ["поэтому"], e: "Второе предложение — следствие первого: «Поэтому выходить на него опасно». Вводные «следовательно», «значит» потребовали бы запятой после себя, а её на месте пропуска нет." },
    { t: "input", q: "Подбери вводное слово со значением примера на место пропуска и запиши его.\n«(1) Многие лекарственные растения растут прямо у дома. (2) <…>, ромашка помогает при воспалении, а подорожник — при порезах.»", a: ["например"], e: "Предложение 2 приводит примеры к первому: «Например, ромашка…»." },
    { t: "input", q: "Подбери наречие на место пропуска и запиши его.\n«(1) Врач долго осматривал пациента. (2) <…> он поставил диагноз и назначил лечение.»", a: ["наконец", "затем", "потом"], e: "Нужна связь по времени: «Наконец (затем) он поставил диагноз…»." },
    { t: "input", q: "Подбери слово со значением уступки или противопоставления на место пропуска и запиши его.\n«(1) Экзамен можно сдать досрочно. (2) <…>, для этого нужно подать заявление заранее.»", a: ["правда", "впрочем"], e: "Второе предложение вносит оговорку, а после пропуска стоит запятая — значит, нужно вводное слово: «Правда, для этого…». «Однако» и «но» в начале предложения в значении «но» — союзы, запятая после них не ставится." },
    { t: "input", q: "Подбери вводное слово, подтверждающее сказанное, на место пропуска и запиши его.\n«(1) Якутск — один из самых холодных крупных городов мира. (2) <…>, зимой температура здесь нередко опускается ниже сорока градусов.»", a: ["действительно", "в самом деле"], e: "Предложение 2 подтверждает мысль первого: «Действительно, зимой…»." },
    { t: "input", q: "Подбери слово со значением вывода на место пропуска и запиши его.\n«(1) Сон нужен не только для отдыха. (2) Во время сна мозг закрепляет то, что человек узнал за день. (3) <…> перед экзаменом важно хорошо выспаться.»", a: ["поэтому"], e: "Предложение 3 — вывод из предыдущих: «Поэтому перед экзаменом…». Вводные «значит», «следовательно», «таким образом» потребовали бы запятой после себя, а её на месте пропуска нет." },
    { t: "input", q: "Подбери вводное сочетание со значением дополнения на место пропуска и запиши его.\n«(1) Пирогов много оперировал в полевых условиях. (2) <…>, он создал атлас топографической анатомии, по которому учились поколения врачей.»", a: ["кроме того", "помимо этого", "помимо того", "более того"], e: "Предложение 2 добавляет ещё одну заслугу: «Кроме того, он создал…»." },
    { t: "input", q: "Подбери наречие на место пропуска и запиши его.\n«(1) Каждый день повторяй хотя бы несколько правил. (2) <…> через месяц их наберётся больше сотни.»", a: ["тогда"], e: "Второе предложение — следствие при условии из первого: «Тогда через месяц…»." },
    { t: "input", q: "Подбери местоимение на место пропуска и запиши его.\n«(1) Мечников изучал клетки, поглощающие микробов. (2) <…> он назвал фагоцитами.»", a: ["их"], e: "«Их он назвал фагоцитами» — местоимение заменяет слово «клетки»." },

    { t: "multi", open: true, q: "Отметь верные характеристики фрагмента.\n«(1) Весной тундра оживает. (2) На кочках расцветают мелкие яркие цветы, а над болотами кружат птицы. (3) Они прилетают сюда с юга, чтобы вывести птенцов.»", o: ["Предложение 2 — сложносочинённое.", "Предложения 2 и 3 связаны с помощью личного местоимения «они».", "В предложении 3 есть придаточная часть цели.", "Предложение 1 — односоставное.", "В предложении 2 есть причастный оборот."], a: [0, 1], e: "«Чтобы вывести птенцов» — оборот с инфинитивом, а не придаточная часть: в нём нет грамматической основы. Предложение 1 двусоставное (тундра оживает)." },
    { t: "multi", open: true, q: "Отметь верные характеристики фрагмента.\n«(1) Мы долго шли по лесу. (2) Наконец впереди показалась река. (3) Её берега заросли ивняком.»", o: ["В предложении 2 слово «наконец» — обстоятельство, а не вводное слово.", "Предложения 2 и 3 связаны с помощью личного местоимения «её».", "Предложение 3 — сложноподчинённое.", "В предложении 1 есть однородные члены.", "Предложение 2 — безличное."], a: [0, 1], e: "«Наконец» здесь значит «после долгого ожидания» и запятыми не выделяется. «Её» заменяет слово «река»." },
    { t: "multi", open: true, q: "Отметь верные характеристики фрагмента.\n«(1) Мечников родился в 1845 году. (2) Он изучал клетки, которые поглощают микробов. (3) За эти работы учёный получил Нобелевскую премию.»", o: ["Предложение 2 — сложноподчинённое с придаточным определительным.", "Предложения 1 и 2 связаны с помощью личного местоимения «он».", "Предложения 2 и 3 связаны с помощью указательного местоимения «эти».", "Слово «учёный» в предложении 3 заменяет фамилию Мечникова.", "Предложение 1 — сложное."], a: [0, 1, 2, 3], e: "Предложение 1 простое: одна грамматическая основа." },
    { t: "multi", open: true, q: "Отметь верные характеристики фрагмента.\n«(1) Ночью ударил мороз. (2) Утром лужи покрылись тонким льдом, и дети, смеясь, скользили по ним.»", o: ["Предложение 2 — сложносочинённое.", "В предложении 2 есть одиночное деепричастие.", "В предложении 1 есть однородные члены.", "Предложение 2 называет следствие того, о чём говорится в предложении 1.", "В предложении 2 есть причастный оборот."], a: [0, 1, 3], e: "«Смеясь» — одиночное деепричастие. Однородных членов в предложении 1 нет, причастного оборота нет." },
    { t: "multi", open: true, q: "Отметь верные характеристики фрагмента.\n«(1) Без пищи человек может прожить несколько недель. (2) Без воды же он проживёт лишь несколько дней. (3) Вот почему так важно пить достаточно жидкости.»", o: ["Предложения 1 и 2 противопоставлены по смыслу.", "Частица «же» в предложении 2 подчёркивает противопоставление.", "Предложение 3 содержит вывод из сказанного.", "Предложение 1 — сложное.", "В предложении 3 есть обращение."], a: [0, 1, 2], e: "Все три предложения — простые, обращений нет." },
    { t: "multi", open: true, q: "Отметь верные характеристики фрагмента.\n«(1) Тайга занимает большую часть Якутии. (2) В ней растут лиственницы, сосны, ели и берёзы. (3) Лиственница лучше других деревьев переносит сильные морозы.»", o: ["В предложении 2 есть однородные подлежащие.", "Предложения 1 и 2 связаны с помощью личного местоимения («в ней»).", "Предложения 2 и 3 связаны лексическим повтором.", "В предложении 3 есть наречие в сравнительной степени.", "Предложение 1 — сложноподчинённое."], a: [0, 1, 2, 3], e: "«Лучше» — сравнительная степень наречия «хорошо». Предложение 1 простое." },
    { t: "multi", open: true, q: "Отметь верные характеристики фрагмента.\n«(1) Чтобы сохранить зрение, врачи советуют делать перерывы. (2) Каждые двадцать минут полезно на несколько секунд перевести взгляд вдаль. (3) Так мышцы глаза отдыхают.»", o: ["Предложение 1 начинается с оборота со значением цели.", "Предложение 1 — сложноподчинённое.", "Предложение 3 поясняет смысл предложения 2.", "Предложение 2 — безличное.", "В предложении 3 есть причастие."], a: [0, 2, 3], e: "«Чтобы сохранить зрение» — оборот с инфинитивом, поэтому предложение 1 простое. Причастий в предложении 3 нет." },
    { t: "multi", open: true, q: "Отметь верные характеристики фрагмента.\n«(1) Учёные давно знают: смех полезен для здоровья. (2) Когда человек смеётся, у него снижается напряжение. (3) Поэтому хорошее настроение помогает лучше учиться.»", o: ["В предложении 1 двоеточие разделяет части бессоюзного сложного предложения.", "Предложение 2 — сложноподчинённое с придаточным времени.", "Предложение 3 связано с предыдущим с помощью слова «поэтому».", "В предложении 2 есть причастный оборот.", "Предложение 1 — простое."], a: [0, 1, 2], e: "Предложение 1 сложное: две грамматические основы и двоеточие между ними." },
    { t: "multi", open: true, q: "Отметь верные характеристики фрагмента.\n«(1) В Якутске есть Музей мамонта. (2) Его экспонаты найдены в вечной мерзлоте. (3) Мерзлота, как гигантский холодильник, сохраняет останки древних животных тысячи лет.»", o: ["Предложения 1 и 2 связаны с помощью местоимения «его».", "Предложения 2 и 3 связаны лексическим повтором.", "В предложении 3 есть сравнительный оборот.", "Предложение 3 — сложное.", "В предложении 2 есть причастный оборот."], a: [0, 1, 2], e: "«Найдены» — краткое причастие в роли сказуемого, а не причастный оборот. Предложение 3 простое." },
    { t: "multi", open: true, q: "Отметь верные характеристики фрагмента.\n«(1) Иммунитет защищает организм от инфекций. (2) Если он ослаблен, человек чаще болеет. (3) Укрепить иммунитет помогают сон, движение и правильное питание.»", o: ["Предложение 2 — сложноподчинённое с придаточным условия.", "Предложения 1 и 2 связаны с помощью личного местоимения «он».", "В предложении 3 есть однородные подлежащие.", "Слово «ослаблен» в предложении 2 — краткое причастие.", "Предложение 3 — сложное."], a: [0, 1, 2, 3], e: "Предложение 3 простое: однородные подлежащие «сон, движение, питание» при одном сказуемом." },

    { t: "input", q: "Прочитай фрагмент словарной статьи. В каком значении употреблено слово ПРОХОДИТЬ в предложении «Экзамен проходит в июне»? Запиши цифру.\n\nПРОХОДИТЬ\n1. Двигаясь, перемещаться через что-либо или мимо чего-либо. Проходить через лес.\n2. Происходить, совершаться. Встреча проходит успешно.\n3. Изучать что-либо. Проходить тему на уроке.\n4. Кончаться, прекращаться. Боль проходит.", a: ["2"], e: "«Экзамен проходит» — происходит, совершается." },
    { t: "input", q: "Прочитай фрагмент словарной статьи. В каком значении употреблено слово ЛЁГКИЙ в предложении «Задание оказалось лёгким»? Запиши цифру.\n\nЛЁГКИЙ\n1. Небольшой по весу. Лёгкий чемодан.\n2. Нетрудный, не требующий больших усилий. Лёгкая задача.\n3. Несильный, слабый. Лёгкий ветер.\n4. Изящный, стройный. Лёгкая походка.", a: ["2"], e: "«Лёгкое задание» — нетрудное." },
    { t: "input", q: "Прочитай фрагмент словарной статьи. В каком значении употреблено слово ЗЕЛЁНЫЙ в предложении «Он ещё совсем зелёный специалист»? Запиши цифру.\n\nЗЕЛЁНЫЙ\n1. Цвета травы. Зелёная листва.\n2. Неспелый. Зелёные яблоки.\n3. Перен. Молодой, неопытный. Зелёная молодёжь.\n4. Связанный с охраной природы. Зелёная экономика.", a: ["3"], e: "«Зелёный специалист» — неопытный, переносное значение." },
    { t: "input", q: "Прочитай фрагмент словарной статьи. В каком значении употреблено слово ГЛУБОКИЙ в предложении «Учёный провёл глубокий анализ данных»? Запиши цифру.\n\nГЛУБОКИЙ\n1. Имеющий большую глубину. Глубокое озеро.\n2. Основательный, всесторонний. Глубокие знания.\n3. Достигший высокой степени. Глубокий сон.\n4. О звуке: низкий. Глубокий голос.", a: ["2"], e: "«Глубокий анализ» — основательный, всесторонний." },
    { t: "input", q: "Прочитай фрагмент словарной статьи. В каком значении употреблено слово ОСТРЫЙ в предложении «Пациента беспокоила острая боль»? Запиши цифру.\n\nОСТРЫЙ\n1. Хорошо режущий или колющий. Острый нож.\n2. Сильный, резко проявляющийся. Острый интерес.\n3. Остроумный, язвительный. Острая шутка.\n4. Пряный, жгучий на вкус. Острый соус.", a: ["2"], e: "«Острая боль» — сильная, резко проявляющаяся." },
    { t: "input", q: "Прочитай фрагмент словарной статьи. В каком значении употреблено слово ТЯЖЁЛЫЙ в предложении «У пациента была тяжёлая форма болезни»? Запиши цифру.\n\nТЯЖЁЛЫЙ\n1. Имеющий большой вес. Тяжёлый рюкзак.\n2. Трудный, требующий больших усилий. Тяжёлая работа.\n3. Опасный, серьёзный (о болезни, ране). Тяжёлое ранение.\n4. Неуживчивый (о характере). Тяжёлый человек.", a: ["3"], e: "«Тяжёлая форма болезни» — опасная, серьёзная." },
    { t: "input", q: "Прочитай фрагмент словарной статьи. В каком значении употреблено слово ВЕРНЫЙ в предложении «Ты выбрал верный путь»? Запиши цифру.\n\nВЕРНЫЙ\n1. Преданный, надёжный. Верный друг.\n2. Правильный, соответствующий истине. Верный ответ.\n3. Несомненный, неизбежный. Верная гибель.", a: ["2"], e: "«Верный путь» — правильный." },
    { t: "input", q: "Прочитай фрагмент словарной статьи. В каком значении употреблено слово ПОДНИМАТЬ в предложении «На собрании подняли вопрос о ремонте»? Запиши цифру.\n\nПОДНИМАТЬ\n1. Брать снизу и держать выше. Поднимать книгу с пола.\n2. Перемещать выше. Поднимать флаг.\n3. Начинать обсуждать, ставить на обсуждение. Поднимать проблему.\n4. Увеличивать. Поднимать цены.", a: ["3"], e: "«Подняли вопрос» — поставили на обсуждение." },
    { t: "input", q: "Прочитай фрагмент словарной статьи. В каком значении употреблено слово ЖИВОЙ в предложении «Ребёнок рос очень живым и любознательным»? Запиши цифру.\n\nЖИВОЙ\n1. Обладающий жизнью. Живой организм.\n2. Подвижный, энергичный, бойкий. Живой характер.\n3. Яркий, выразительный. Живой рассказ.\n4. Непосредственный, личный. Живое общение.", a: ["2"], e: "«Живой ребёнок» — подвижный, бойкий." },
    { t: "input", q: "Прочитай фрагмент словарной статьи. В каком значении употреблено слово ХОЛОДНЫЙ в предложении «Он ответил холодным тоном»? Запиши цифру.\n\nХОЛОДНЫЙ\n1. Имеющий низкую температуру. Холодная вода.\n2. Неприветливый, равнодушный. Холодный взгляд.\n3. Плохо защищающий от холода. Холодное пальто.\n4. О цвете: с голубоватым оттенком. Холодные тона.", a: ["2"], e: "«Холодный тон» — неприветливый, равнодушный." }
  ]);

  // ---------- Задания 22–25. Анализ текста ----------
  add("r0-2", [
    { t: "multi", open: true, ctx: "d", q: "Какие из высказываний соответствуют содержанию текста?", o: ["Дженнер заметил, что доярки, переболевшие коровьей оспой, почти не заражались натуральной.", "Опыт Дженнера был проведён в начале XX века.", "Слово «вакцинация» происходит от латинского слова со значением «корова».", "Метод Дженнера сразу и все приняли с доверием.", "Оспа — единственная болезнь человека, полностью уничтоженная прививками."], a: [0, 2, 4], e: "Опыт проведён в 1796 году, в конце XVIII века (предложение 4); поначалу многие относились к методу с недоверием (предложение 8)." },
    { t: "multi", open: true, ctx: "d", q: "Какие из высказываний соответствуют содержанию текста?", o: ["Мальчику, которому сделали прививку, было восемь лет.", "После прививки мальчик тяжело переболел натуральной оспой.", "О победе над оспой было объявлено в 1980 году.", "Коровья оспа опасна для человека.", "Оспа оставляла у выживших рубцы на лицах."], a: [0, 2, 4], e: "Мальчик не заболел (предложение 6), а коровья оспа лёгкая и неопасная для человека (предложение 3)." },
    { t: "multi", open: true, ctx: "d", q: "Какие из утверждений являются верными?", o: ["В предложениях 4–6 представлено повествование.", "Предложение 3 поясняет содержание предложения 2.", "Предложение 7 подводит итог описанным событиям.", "Предложения 9–10 содержат рассуждение.", "В предложении 6 представлено описание."], a: [0, 1, 2], e: "Предложение 3 раскрывает, какой «любопытный факт» заметил Дженнер. В предложениях 9–10 сообщаются факты, рассуждения там нет." },
    { t: "single", ctx: "d", q: "Какой тип речи представлен в предложениях 2–6?", o: ["повествование", "описание", "рассуждение"], a: 0, e: "События идут одно за другим: заметил, решился, привил, мальчик не заболел." },
    { t: "input", ctx: "d", q: "Из предложения 8 выпиши антонимы (антонимическую пару).", a: ["доверие недоверием", "недоверием доверие"], e: "«Доверие» — «недоверием»." },
    { t: "input", ctx: "d", q: "Из предложения 1 выпиши слово со значением «шрамы, следы зажившей раны».", a: ["рубцы"], e: "Рубцы — шрамы." },
    { t: "input", d: true, ctx: "d", q: "Среди предложений 4–7 найди такое, которое связано с предыдущим с помощью личного местоимения. Запиши номер.", a: ["5"], e: "Предложение 5: «Он привил…» — местоимение заменяет фамилию Дженнера." },
    { t: "input", d: true, ctx: "d", q: "Среди предложений 5–10 найди такое, которое связано с предыдущим с помощью лексического повтора. Запиши номер.", a: ["6"], e: "Предложение 6: «Мальчик не заболел» — повтор слова «мальчику» из предложения 5." },

    { t: "multi", open: true, ctx: "e", q: "Какие из высказываний соответствуют содержанию текста?", o: ["Мечников проводил опыты на личинках морской звезды.", "Опыт с шипом розы Мечников провёл в 1908 году.", "Подвижные клетки собрались вокруг занозы.", "Коллеги сразу поддержали идею Мечникова.", "Слово «фагоцит» пришло из греческого языка."], a: [0, 2, 4], e: "Опыты — в 1882 году (предложение 1), а коллеги сначала отнеслись к идее скептически (предложение 7)." },
    { t: "multi", open: true, ctx: "e", q: "Какие из высказываний соответствуют содержанию текста?", o: ["Мечников получил Нобелевскую премию в 1908 году.", "Фагоциты — единственная часть системы иммунитета.", "Учёный предположил, что подвижные клетки защищают организм от чужого.", "Опыты проводились в Москве.", "Новые опыты подтвердили догадку Мечникова."], a: [0, 2, 4], e: "Фагоциты — лишь одна часть системы иммунитета (предложение 10), опыты проводились на Сицилии (предложение 1)." },
    { t: "multi", open: true, ctx: "e", q: "Какие из утверждений являются верными?", o: ["В предложениях 1–4 представлено повествование.", "Предложение 6 поясняет значение слова «фагоциты».", "Предложение 8 противопоставлено по смыслу предложению 7.", "В предложениях 9–10 представлено описание.", "Предложение 5 содержит описание внешнего вида клеток."], a: [0, 1, 2], e: "Предложение 5 — догадка учёного, а не описание; в предложениях 9–10 описания нет." },
    { t: "single", ctx: "e", q: "Какое утверждение верно?", o: ["Предложение 5 содержит вывод, к которому пришёл учёный.", "Предложение 1 содержит рассуждение.", "В предложениях 7–8 представлено описание.", "Предложение 10 рассказывает о событиях 1882 года."], a: 0, e: "«Учёного осенила догадка: такие клетки защищают организм» — это вывод из наблюдения." },
    { t: "input", ctx: "e", q: "Из предложения 3 выпиши слово, которое в предложении 4 заменено словом «заноза».", a: ["шип"], e: "Шип розы в предложении 4 назван занозой." },
    { t: "input", ctx: "e", q: "Из предложения 7 выпиши слово со значением «с сомнением, недоверчиво».", a: ["скептически"], e: "Скептически — с сомнением." },
    { t: "input", d: true, ctx: "e", q: "Среди предложений 1–4 найди такие, которые связаны с предыдущими с помощью личного местоимения. Запиши номера.", a: ["24"], e: "Предложения 2 («Он наблюдал») и 4 («он увидел»)." },
    { t: "input", d: true, ctx: "e", q: "Среди предложений 7–10 найди такое, которое связано с предыдущим с помощью противительного союза. Запиши номер.", a: ["8"], e: "Предложение 8 начинается с союза «Однако»." },

    { t: "multi", open: true, ctx: "f", q: "Какие из высказываний соответствуют содержанию текста?", o: ["Мамонтиху Юку обнаружили в 2010 году.", "В мерзлоте находят только кости животных.", "Музей мамонта работает при Северо-Восточном федеральном университете.", "Юку нашли в центре Якутска.", "У Юки хорошо сохранились мышцы и ткани."], a: [0, 2, 4], e: "Находят не только кости, но и шерсть, кожу, мышцы (предложение 4); Юку нашли на побережье моря Лаптевых (предложение 5)." },
    { t: "multi", open: true, ctx: "f", q: "Какие из высказываний соответствуют содержанию текста?", o: ["Мерзлота сохраняет ткани животных тысячи лет.", "В мерзлоте находят останки шерстистых носорогов.", "Сотрудники музея не участвуют в экспедициях.", "Учёные из других стран не изучают якутские находки.", "Многие находки хранятся в Музее мамонта."], a: [0, 1, 4], e: "Сотрудники музея участвуют в экспедициях и работают вместе с учёными из разных стран (предложение 9)." },
    { t: "multi", open: true, ctx: "f", q: "Какие из утверждений являются верными?", o: ["Предложение 3 поясняет, почему в мерзлоте сохраняются останки.", "Предложение 4 содержит вывод из предложения 3.", "В предложениях 7–9 представлено повествование о поездке в музей.", "В предложении 2 перечисляются животные ледникового периода.", "Предложение 6 противопоставлено предложению 5."], a: [0, 1, 3], e: "В предложениях 7–9 рассказывается о музее, но не о поездке; предложение 6 развивает мысль предложения 5." },
    { t: "single", ctx: "f", q: "Какой тип речи представлен в предложениях 3–4?", o: ["рассуждение", "повествование", "описание"], a: 0, e: "Причина (холод сохраняет ткани) и следствие («Поэтому учёные находят…»)." },
    { t: "input", ctx: "f", q: "Из предложения 5 выпиши слово, называющее самку мамонта.", a: ["мамонтиха"], e: "Мамонтиха — самка мамонта." },
    { t: "input", ctx: "f", q: "Из предложения 2 выпиши слово со значением «очень долго, на протяжении многих веков».", a: ["веками"], e: "Веками — в течение многих веков." },
    { t: "input", d: true, ctx: "f", q: "Среди предложений 1–4 найди такое, которое связано с предыдущим с помощью личного местоимения. Запиши номер.", a: ["2"], e: "Предложение 2: «В ней…» — местоимение заменяет слово «мерзлота»." },
    { t: "input", d: true, ctx: "f", q: "Среди предложений 6–9 найди такие, которые связаны с предыдущими с помощью личного или указательного местоимения. Запиши номера.", a: ["689"], e: "6 — «Её тело», 8 — «Этот музей», 9 — «Его сотрудники»." },

    { t: "multi", open: true, ctx: "g", q: "Какие из высказываний соответствуют содержанию текста?", o: ["Многие школьники перед экзаменом занимаются допоздна.", "Исследования показывают, что недостаток сна помогает запоминать.", "Во время сна мозг закрепляет новые знания.", "Врачи советуют перед экзаменом не спать всю ночь.", "Сон не заменяет подготовку к экзамену."], a: [0, 2, 4], e: "Недостаток сна мешает учиться (предложение 3), а врачи советуют лечь спать вовремя (предложение 7)." },
    { t: "multi", open: true, ctx: "g", q: "Какие из высказываний соответствуют содержанию текста?", o: ["Во время сна мозг полностью отключается.", "Если спать слишком мало, закрепление знаний нарушается.", "Свежая голова справляется с заданиями лучше уставшей.", "Каждый лишний час ночных занятий гарантирует высокие баллы.", "Без сна легко забыть даже хорошо выученное."], a: [1, 2, 4], e: "Мозг во сне продолжает работать (предложение 4); мнение о «лишнем часе» в тексте опровергается (предложения 2–3)." },
    { t: "multi", open: true, ctx: "g", q: "Какие из утверждений являются верными?", o: ["Предложение 3 противопоставлено по смыслу предложению 2.", "Предложение 7 содержит вывод из предложений 4–6.", "Предложение 5 поясняет содержание предложения 4.", "В предложениях 1–2 представлено повествование о событиях одного дня.", "Предложение 9 содержит описание."], a: [0, 1, 2], e: "В предложениях 1–2 говорится об обычной привычке, а не о событиях одного дня; предложение 9 — часть рассуждения." },
    { t: "single", ctx: "g", q: "Какой тип речи преобладает в тексте?", o: ["рассуждение", "повествование", "описание"], a: 0, e: "Автор доказывает мысль, что сон нужен для учёбы, приводит объяснения и делает вывод." },
    { t: "input", ctx: "g", q: "Из предложения 8 выпиши контекстные антонимы.", a: ["свежая уставшая", "уставшая свежая"], e: "«Свежая» — «уставшая» (голова)." },
    { t: "input", ctx: "g", q: "Из предложения 1 выпиши устойчивое сочетание со значением «до очень позднего времени».", a: ["до глубокой ночи"], e: "«До глубокой ночи» — устойчивое сочетание: до очень позднего времени." },
    { t: "input", d: true, ctx: "g", q: "Среди предложений 1–5 найди такое, которое связано с предыдущим с помощью противительного союза. Запиши номер.", a: ["3"], e: "Предложение 3 начинается с союза «Однако»." },
    { t: "input", d: true, ctx: "g", q: "Среди предложений 4–6 найди такое, которое связано с предыдущим с помощью личного местоимения. Запиши номер.", a: ["5"], e: "Предложение 5: «Он перебирает…» — местоимение заменяет слово «мозг»." },

    { t: "multi", open: true, ctx: "h", q: "Какие из высказываний соответствуют содержанию текста?", o: ["Флеминг обнаружил плесень, вернувшись из отпуска.", "Чистый пенициллин выделил сам Флеминг в 1928 году.", "Вокруг плесени бактерии погибли.", "Нобелевскую премию за пенициллин получил только Флеминг.", "Пенициллин спас многих раненых во время Второй мировой войны."], a: [0, 2, 4], e: "Чистое лекарство выделили Флори и Чейн (предложение 6), и премию получили все трое (предложение 8)." },
    { t: "multi", open: true, ctx: "h", q: "Какие из высказываний соответствуют содержанию текста?", o: ["Флеминг был шотландским учёным.", "Антибиотики можно принимать без назначения врача.", "Бактерии постепенно становятся устойчивыми к антибиотикам.", "Чистое лекарство выделили Флори и Чейн.", "Плесень выросла на всех чашках в лаборатории."], a: [0, 2, 3], e: "Принимать антибиотики можно только по назначению (предложение 10); плесень выросла на одной из чашек (предложение 2)." },
    { t: "multi", open: true, ctx: "h", q: "Какие из утверждений являются верными?", o: ["В предложениях 1–3 представлено повествование.", "Предложение 4 содержит вывод, который сделал учёный.", "Предложение 6 противопоставлено по смыслу предложениям 4–5.", "Предложение 10 содержит вывод из предложения 9.", "В предложении 8 представлено описание лаборатории."], a: [0, 1, 2, 3], e: "Предложение 8 сообщает о премии, описания лаборатории в нём нет." },
    { t: "single", ctx: "h", q: "Какой тип речи представлен в предложениях 9–10?", o: ["рассуждение", "повествование", "описание"], a: 0, e: "Утверждение (бактерии становятся устойчивыми) и вывод («Поэтому…»)." },
    { t: "input", ctx: "h", q: "Из предложения 4 выпиши слово со значением «смертельный, уничтожающий».", a: ["губительное"], e: "Губительное — несущее гибель." },
    { t: "input", ctx: "h", q: "Из предложения 3 выпиши антонимы (антонимическую пару).", a: ["мертвы живы", "живы мертвы"], e: "«Мертвы» — «живы»." },
    { t: "input", d: true, ctx: "h", q: "Среди предложений 2–5 найди такие, которые связаны с предыдущими с помощью личного местоимения. Запиши номера.", a: ["235"], e: "2 — «он заметил», 3 — «Вокруг неё», 5 — «Он назвал его»." },
    { t: "input", d: true, ctx: "h", q: "Среди предложений 5–8 найди такое, которое связано с предыдущим с помощью противительного союза. Запиши номер.", a: ["6"], e: "Предложение 6 начинается с союза «Однако»." }
  ], {
    d: "(1) Оспа на протяжении веков была одной из самых страшных болезней: она убивала миллионы людей и оставляла на лицах выживших глубокие рубцы. (2) В конце XVIII века английский врач Эдвард Дженнер обратил внимание на любопытный факт. (3) Доярки, переболевшие коровьей оспой, лёгкой и неопасной для человека, почти никогда не заражались натуральной оспой. (4) В 1796 году Дженнер решился на смелый опыт. (5) Он привил коровью оспу восьмилетнему мальчику Джеймсу Фиппсу, а через несколько недель ввёл ему материал от больного натуральной оспой. (6) Мальчик не заболел. (7) Так появилась вакцинация — от латинского слова vacca, что значит «корова». (8) Метод постепенно завоевал доверие врачей, хотя поначалу многие относились к нему с недоверием. (9) Почти через двести лет, в 1980 году, Всемирная организация здравоохранения объявила, что оспа на Земле побеждена. (10) Это первая и пока единственная болезнь человека, которую удалось полностью уничтожить с помощью прививок.",
    e: "(1) В 1882 году русский учёный Илья Ильич Мечников проводил опыты на морском побережье Сицилии. (2) Он наблюдал под микроскопом прозрачных личинок морской звезды. (3) Однажды Мечников ввёл в личинку тонкий шип розы. (4) На следующее утро он увидел, что вокруг занозы собрались подвижные клетки, которые словно пытались её поглотить. (5) Учёного осенила догадка: такие клетки защищают организм, уничтожая всё чужое. (6) Мечников назвал их фагоцитами, что в переводе с греческого означает «клетки-пожиратели». (7) Сначала многие коллеги встретили эту идею скептически. (8) Однако новые опыты подтвердили правоту исследователя. (9) В 1908 году Мечникову была присуждена Нобелевская премия. (10) Сегодня известно, что фагоциты — лишь одна часть сложной системы иммунитета, но первый шаг к её пониманию сделал именно он.",
    f: "(1) Вечная мерзлота Якутии хранит удивительные находки. (2) В ней веками лежат останки мамонтов, шерстистых носорогов, древних лошадей и других животных ледникового периода. (3) Холод работает как огромный природный холодильник: ткани не разрушаются тысячи лет. (4) Поэтому учёные иногда находят не только кости, но и шерсть, кожу и даже мышцы. (5) Одной из самых известных находок стала мамонтиха Юка, обнаруженная в 2010 году на побережье моря Лаптевых. (6) Её тело сохранилось так хорошо, что исследователи смогли изучить строение мышц и тканей. (7) Многие находки хранятся в Музее мамонта в Якутске. (8) Этот музей работает при Северо-Восточном федеральном университете. (9) Его сотрудники участвуют в экспедициях и изучают древних животных вместе с учёными из разных стран.",
    g: "(1) Многие школьники перед экзаменом сидят над учебниками до глубокой ночи. (2) Им кажется, что каждый лишний час занятий прибавит баллов. (3) Однако исследования показывают обратное: недостаток сна мешает и учиться, и вспоминать выученное. (4) Во время сна мозг не отдыхает, как принято думать, а продолжает работать. (5) Он перебирает впечатления дня и закрепляет новые знания. (6) Если человек спит слишком мало, этот процесс нарушается. (7) Вот почему врачи советуют перед экзаменом лечь спать вовремя. (8) Свежая голова справится с заданиями лучше, чем уставшая. (9) Конечно, сон не заменит подготовку, но без него даже хорошо выученное легко забыть.",
    h: "(1) Летом 1928 года шотландский учёный Александр Флеминг уехал в отпуск, оставив в лаборатории чашки с культурами бактерий. (2) Вернувшись, он заметил, что на одной из чашек выросла плесень. (3) Вокруг неё бактерии были мертвы, а подальше — живы. (4) Флеминг понял, что плесень выделяет вещество, губительное для микробов. (5) Он назвал его пенициллином. (6) Однако выделить чистое лекарство удалось лишь через десять с лишним лет другим учёным — Говарду Флори и Эрнсту Чейну. (7) Во время Второй мировой войны пенициллин спас жизни тысячам раненых. (8) В 1945 году Флеминг, Флори и Чейн получили Нобелевскую премию. (9) Сегодня антибиотиков много, но бактерии постепенно становятся к ним устойчивыми. (10) Поэтому врачи напоминают: принимать антибиотики можно только по назначению и строго по схеме."
  });

